import * as types from './types.js';
import { setSelectedBrand } from '@jsroot/actions/brandAction';

const setReportFilter = data => {
    return {
        type: types.SET_REPORT_FILTER,
        data: data
    }
}

const setDetailParams = data => {
    return {
        type: types.SET_DETAIL_PARAMS,
        data: data
    }
}


export default {
    setReportFilter,
    setDetailParams,
    setSelectedBrand
}
